350	                None
351	            } else if remainder_os.is_empty() {
352	                debug_assert!(self.is_stdio());
353	                None
354	            } else {
355	                Some(ShortFlags::new(remainder_os))
356	            }
357	        } else {
358	            None
359	        }
360	    }
