    assert_data_eq!(
        complete!(command(), "-xt v1 [TAB]"),
        snapbox::str![[r#"
--fast
--safe
--tag
--help	Print help
"#]],
    );

    // After `--` only positionals are completed (none here); state parsed from
    // the preceding short options stays valid.
    assert_data_eq!(complete!(command(), "-f -- [TAB]"), snapbox::str![""]);
