#![cfg(feature = "unstable-dynamic")]

use clap::Command;

fn names(cmd: &mut Command, args: Vec<std::ffi::OsString>, idx: usize) -> Vec<String> {
    clap_complete::engine::complete(cmd, args, idx, None)
        .map(|v| {
            v.into_iter()
                .map(|c| {
                    let val = c.get_value().to_str().unwrap().to_owned();
                    match c.get_help() {
                        Some(h) => format!("{val}\t{h}"),
                        None => val,
                    }
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_else(|e| vec![format!("<ERR: {e}>")])
}

fn bin(args: &[&str]) -> (Vec<std::ffi::OsString>, usize) {
    let mut v = vec!["exhaustive".into()];
    v.extend(args.iter().map(|s| (*s).into()));
    let idx = v.len() - 1;
    (v, idx)
}

fn cmd_conflict() -> Command {
    Command::new("exhaustive")
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .visible_alias("quick")
                .alias("speedy")
                .action(clap::ArgAction::SetTrue)
                .conflicts_with("safe"),
        )
        .arg(
            clap::Arg::new("safe")
                .long("safe")
                .short('s')
                .action(clap::ArgAction::SetTrue),
        )
        .arg(
            clap::Arg::new("tag")
                .long("tag")
                .short('t')
                .value_parser(["v1", "v2"])
                .conflicts_with("fast"),
        )
}

#[test]
fn probe() {
    let cases: Vec<(&str, Vec<&str>)> = vec![
        // (label, args), cursor always on final arg
        ("closed equals, conflict", vec!["--tag=v1", ""]),
        ("closed space, conflict", vec!["--tag", "v1", ""]),
        ("editing equals empty", vec!["--tag="]),
        ("editing equals prefix", vec!["--tag=v"]),
        ("closed equals then other opt present", vec!["--tag=v1", "--f"]),
        ("closed equals, after --", vec!["--tag=v1", "--", ""]),
        ("unknown long equals editing", vec!["--nope="]),
        ("unknown long equals closed", vec!["--nope=x", ""]),
        ("flag (no value) with equals, editing", vec!["--fast="]),
        ("flag (no value) with equals closed", vec!["--fast=x", ""]),
        ("visible alias equals editing", vec!["--quick="]),
        ("short equals editing", vec!["-t="]),
        ("short equals closed conflict", vec!["-t=v1", ""]),
        ("short attached closed conflict", vec!["-tv1", ""]),
        ("closed equals conflicts with positional hyphen allow", vec![]),
    ];
    for (label, args) in cases {
        let mut cmd = cmd_conflict();
        let (v, idx) = bin(&args);
        println!("=== {label}: {v:?} ===");
        for line in names(&mut cmd, v, idx) {
            println!("    {line}");
        }
    }

    // delimiter / multiple probes
    let mut cmd = Command::new("exhaustive")
        .arg(
            clap::Arg::new("delimiter")
                .long("delimiter")
                .short('D')
                .value_parser(["comma", "space", "tab"])
                .value_delimiter(',')
                .conflicts_with("other"),
        )
        .arg(clap::Arg::new("other").long("other").action(clap::ArgAction::SetTrue))
        .arg(clap::Arg::new("pos").value_parser(["a_pos", "b_pos", "c_pos"]));
    for args in [
        vec!["--delimiter=comma,"],
        vec!["--delimiter=comma,space", ""],
        vec!["--delimiter=comma,space", "--o"],
        vec!["-D=comma,"],
        vec!["-D=comma,space", ""],
    ] {
        let (v, idx) = bin(&args);
        println!("=== delim: {v:?} ===");
        let mut cmd = cmd.clone();
        for line in names(&mut cmd, v, idx) {
            println!("    {line}");
        }
    }

    // multiple values (num_args > 1), equals form
    let mut cmd = Command::new("exhaustive")
        .arg(
            clap::Arg::new("nums")
                .long("nums")
                .num_args(1..=3)
                .value_parser(["one", "two", "three"])
                .conflicts_with("other"),
        )
        .arg(clap::Arg::new("other").long("other").action(clap::ArgAction::SetTrue));
    for args in [vec!["--nums=", ""], vec!["--nums=one", ""], vec!["--nums=one", "--"]] {
        let (v, idx) = bin(&args);
        println!("=== multi: {v:1?} ===");
        for line in names(&mut cmd, v, idx) {
            println!("    {line}");
        }
    }

    // non-UTF8
    let mut cmd = cmd_conflict();
    let v: Vec<std::ffi::OsString> = vec![
        "exhaustive".into(),
        std::ffi::OsString::from_vec(b"--tag=\xff".to_vec()),
    ];
    println!("=== non-utf8 editing equals ===");
    for line in names(&mut cmd, v, 1) {
        println!("    {line}");
    }

    // no_binary_name first word
    let mut cmd = Command::new("exhaustive")
        .no_binary_name(true)
        .arg(
            clap::Arg::new("tag")
                .long("tag")
                .value_parser(["v1", "v2"])
                .conflicts_with("fast"),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .action(clap::ArgAction::SetTrue),
        );
    let v: Vec<std::ffi::OsString> = vec!["--tag=v1".into(), "".into()];
    println!("=== no_binary_name closed equals ===");
    for line in names(&mut cmd, v, 1) {
        println!("    {line}");
    }
}

