#![cfg(feature = "unstable-dynamic")]

use clap::Command;

fn names(cmd: &mut Command, args: Vec<std::ffi::OsString>, idx: usize) -> Vec<String> {
    clap_complete::engine::complete(cmd, args, idx, None)
        .map(|v| {
            v.into_iter()
                .map(|c| {
                    let val = c.get_value().to_str().unwrap().to_owned();
                    match c.get_help() {
                        Some(h) => format!("{val}\t{h}"),
                        None => val,
                    }
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_else(|e| vec![format!("<ERR: {e}>")])
}

fn bin(args: &[&str]) -> (Vec<std::ffi::OsString>, usize) {
    let mut v = vec!["exhaustive".into()];
    v.extend(args.iter().map(|s| (*s).into()));
    let idx = v.len() - 1;
    (v, idx)
}

