            .arg_ids()
            .filter(|arg_id| {
                matcher.check_explicit(arg_id, &crate::builder::ArgPredicate::IsPresent)
            })
            .filter(|&n| {
                self.cmd
                    .find(n)
                    .map(|a| !(a.is_hide_set() || required.contains(a.get_id())))
                    .unwrap_or(true)
            })
            .cloned()
            .collect();
        used.push(arg.get_id().clone());

