        })
    } else {
        debug!("Parser::parse_long_arg({long_arg:?}): Presence validated");
        let trailing_idx = None;
        self.react(
            Some(ident),
            ValueSource::CommandLine,
            arg,
            vec![],
            trailing_idx,
            matcher,
