use std::os::unix::ffi::OsStringExt;
use clap::Command;
fn names(cmd: &mut Command, v: Vec<std::ffi::OsString>) -> Result<Vec<String>,String> {
    let idx = v.len()-1;
    clap_complete::engine::complete(cmd, v, idx, None)
        .map(|cs| cs.iter().map(|c| c.get_value().to_string_lossy().into_owned()).collect())
        .map_err(|e| e.to_string())
}
fn main() {
    let mut cmd = Command::new("ex")
        .arg(clap::Arg::new("tag").long("tag").visible_alias("label").alias("ticket").value_parser(["red","blue"]).conflicts_with("fast"))
        .arg(clap::Arg::new("fast").long("fast").action(clap::ArgAction::SetTrue));
    // non-UTF8 value editing
    println!("nonutf editing: {:?}", names(&mut cmd, vec!["ex".into(), OsString::from_vec(b"--tag=\xff".to_vec())]));
